static void facRango(LinkedList<Integer>L,int n,int i,int b){
    int p=prod(L);

    if(p>=n){
        if(p==n)System.out.println(L);
        return;
    }

    for(int k=i;k<=b;k++)
        if(n%(p*k)==0){
            L.add(k);
            facRango(L,n,k,b);
            L.removeLast();
        }
}
